:root {
  --bg: #1e1e2f;
  --card-back: #2d2d44;
  --card-front: #f0f0f0;
  --accent: #ff6b6b;
  --accent-hover: #ff5252;
  --text: #f0f0f0;
  --text-muted: #a0a0b0;
  --focus: #ffd93d;
  --matched: #4ecdc4;
  --radius: 10px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  width: 100%;
  max-width: 520px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.game-header {
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 4px;
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
}

.game-info {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.move-counter {
  font-size: 1.125rem;
  font-weight: 600;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 20px;
  border: 2px solid var(--accent);
  border-radius: var(--radius);
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.btn:active {
  transform: scale(0.96);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  aspect-ratio: 1 / 1;
}

.card {
  position: relative;
  perspective: 600px;
  cursor: pointer;
  border: none;
  background: none;
  padding: 0;
  border-radius: var(--radius);
  transition: transform 0.1s;
}

.card:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.card:active {
  transform: scale(0.95);
}

.card-inner {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transition: transform 0.4s ease;
  border-radius: var(--radius);
}

.card.flipped .card-inner {
  transform: rotateY(180deg);
}

.card-face {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
}

.card-back {
  background: var(--card-back);
  border: 2px solid #3d3d5c;
  color: var(--text-muted);
}

.card-front {
  background: var(--card-front);
  transform: rotateY(180deg);
  border: 2px solid #ddd;
}

.card.matched .card-front {
  background: var(--matched);
  border-color: var(--matched);
  color: #fff;
}

.card.matched {
  cursor: default;
}

.win-message {
  text-align: center;
  padding: 20px;
  background: var(--card-back);
  border-radius: var(--radius);
  border: 2px solid var(--matched);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.win-message p {
  font-size: 1.25rem;
  font-weight: 600;
}

@media (max-width: 400px) {
  .game-board {
    gap: 6px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .game-info {
    justify-content: center;
  }
}

const COLORS = [
  '#ff6b6b', '#4ecdc4', '#ffd93d', '#6c5ce7',
  '#fd79a8', '#00b894', '#e17055', '#0984e3'
];

const board = document.getElementById('gameBoard');
const moveCountEl = document.getElementById('moveCount');
const winMessage = document.getElementById('winMessage');
const finalMoves = document.getElementById('finalMoves');
const newGameBtn = document.getElementById('newGameBtn');
const playAgainBtn = document.getElementById('playAgainBtn');

let deck = [];
let flipped = [];
let matched = 0;
let moves = 0;
let lock = false;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createDeck() {
  const cards = [];
  COLORS.forEach((color, index) => {
    cards.push({ id: index, color });
    cards.push({ id: index, color });
  });
  return shuffle(cards);
}

function renderBoard() {
  board.innerHTML = '';
  deck.forEach((card, i) => {
    const btn = document.createElement('button');
    btn.className = 'card';
    btn.type = 'button';
    btn.setAttribute('aria-label', 'Card ' + (i + 1) + ', hidden');
    btn.dataset.index = i;
    btn.dataset.id = card.id;

    const inner = document.createElement('div');
    inner.className = 'card-inner';

    const back = document.createElement('div');
    back.className = 'card-face card-back';
    back.textContent = '?';

    const front = document.createElement('div');
    front.className = 'card-face card-front';
    front.style.background = card.color;

    inner.appendChild(back);
    inner.appendChild(front);
    btn.appendChild(inner);
    btn.addEventListener('click', handleCardClick);
    board.appendChild(btn);
  });
}

function handleCardClick(e) {
  const card = e.currentTarget;
  if (lock || card.classList.contains('flipped') || card.classList.contains('matched')) return;

  card.classList.add('flipped');
  card.setAttribute('aria-label', 'Card ' + (parseInt(card.dataset.index) + 1) + ', revealed');
  flipped.push(card);

  if (flipped.length === 2) {
    moves++;
    moveCountEl.textContent = moves;
    lock = true;
    checkMatch();
  }
}

function checkMatch() {
  const [a, b] = flipped;
  if (a.dataset.id === b.dataset.id) {
    a.classList.add('matched');
    b.classList.add('matched');
    a.setAttribute('aria-label', 'Card ' + (parseInt(a.dataset.index) + 1) + ', matched');
    b.setAttribute('aria-label', 'Card ' + (parseInt(b.dataset.index) + 1) + ', matched');
    matched++;
    flipped = [];
    lock = false;
    if (matched === COLORS.length) {
      setTimeout(showWin, 400);
    }
  } else {
    setTimeout(() => {
      a.classList.remove('flipped');
      b.classList.remove('flipped');
      a.setAttribute('aria-label', 'Card ' + (parseInt(a.dataset.index) + 1) + ', hidden');
      b.setAttribute('aria-label', 'Card ' + (parseInt(b.dataset.index) + 1) + ', hidden');
      flipped = [];
      lock = false;
    }, 800);
  }
}

function showWin() {
  finalMoves.textContent = moves;
  winMessage.hidden = false;
  playAgainBtn.focus();
}

function resetGame() {
  deck = createDeck();
  flipped = [];
  matched = 0;
  moves = 0;
  lock = false;
  moveCountEl.textContent = '0';
  winMessage.hidden = true;
  renderBoard();
  newGameBtn.focus();
}

newGameBtn.addEventListener('click', resetGame);
playAgainBtn.addEventListener('click', resetGame);

resetGame();
